mutations.old:
var highest string
found := false
for _, version := range applied {
	source, ok := sourceVersions[version]
	if !ok {
		continue
	}
	if !found || source > highest {
		highest, found = source, true
	}
}
return highest, found

mutations.new:
var highest string
var highestVersion int64
found := false
for _, version := range applied {
	source, ok := sourceVersions[version]
	if !ok {
		continue
	}
	if !found || version > highestVersion {
		highest, highestVersion, found = source, version, true
	}
}
return highest, found
